import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/SKK.html","title":"SKK","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":0.94,"words":281},"filePathRelative":"SKK.md"}`),a={name:`SKK.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="skk" tabindex="-1"><a class="header-anchor" href="#skk"><span>SKK</span></a></h1><p><a href="./Rhinocs.html">Rhinocs</a></p><ul><li><a href="https://ddskk.readthedocs.io/ja/latest/" target="_blank" rel="noopener noreferrer">SKK (Simple Kana to Kanji conversion program) Manual — ddskk 17.1 ドキュメント</a> 本家のドキュメントはここという事になるんだろうか。</li><li><a href="https://github.com/karino2/RhinocsSKK/" target="_blank" rel="noopener noreferrer">karino2/RhinocsSKK: SKK port for Rhinocs</a> <a href="./Rhinocs.html">Rhinocs</a>上のSKK。 <ul><li><a href="https://github.com/hkurokawa/chrome-skk/tree/main" target="_blank" rel="noopener noreferrer">hkurokawa/chrome-skk: An SKK implementation for ChromeOS IME API.</a> ChromeOS用(jmuk版)をhkurokawa氏がメンテしているもの、RhinocsSKKの派生元</li><li><a href="https://github.com/loyaltouch/Skk-Mode/tree/master" target="_blank" rel="noopener noreferrer">loyaltouch/Skk-Mode: xyzzy-skk-mode</a> xyzzyのSkk-Mode。実装が単純なのに普通に使えるので良く参考にしている。</li></ul></li></ul><p>実装が簡単で辞書も小さく、けれどかなり実用になる凄いIME。送り仮名でちょっと使う側が頭を使う。 自分が学生の頃はnemacsにSKKを使っていた。</p><h2 id="rhinocsskk" tabindex="-1"><a class="header-anchor" href="#rhinocsskk"><span>RhinocsSKK</span></a></h2><p><a href="https://github.com/karino2/RhinocsSKK/" target="_blank" rel="noopener noreferrer">karino2/RhinocsSKK: SKK port for Rhinocs</a> このページは主にこれを扱う。</p><p><a href="./Rhinocs.html">Rhinocs</a>上に移植したSKKだが、辞書のロードなどはkotlin側で書いている。<a href="./Rhinocs.html">Rhinocs</a>はどうせSKKでしか使わない予定なのでかなり特別扱いしている。 innerSKKは廃止してダイアログでAndroidのEditTextを出すような作りにしている（外部のIMEで漢字が登録出来るように）。</p><p><strong>Dogfoodメモ</strong></p><ul><li>DONE ... ダイアログをC-gでキャンセルした時の状態をちゃんと戻す</li><li>DONE ... preeditでC-nとかが動くのも良くない</li><li>DONE ... preeditでC-kが効いているがたぶん良く無い。(でもどうするのがいいかな？)</li><li>DONE ... ｢りふぁk｣と入力してバックスペースを二回以上押してもkより前が消えない</li><li>DONE ... cyuuで｢ちゅう｣にならない</li><li>DONE ... cyauで｢ちゃう｣にならない。</li><li>DONE ... hiraganaでは＞記号は全角にしたい(良く使うので)</li></ul><h3 id="キャレットの移動はサポートしない事に-2026-06-26-金" tabindex="-1"><a class="header-anchor" href="#キャレットの移動はサポートしない事に-2026-06-26-金"><span>キャレットの移動はサポートしない事に 2026-06-26 (金)</span></a></h3><p>clearCompositionとか確定の周辺は、バッファに直接かきこんでいるRhinocsと変換用の特別な状態を持つと思われるChromeOSで結構違いがでて、 つじつまをあわせるのが難しい。</p><p>そこでpreeditでの左矢印などの移動はサポートしない事にする。 preedit中は知らないキーはデフォルトに流すのではなく握りつぶす事にした。</p><h3 id="変換途中のundoの試行錯誤撤退メモ" tabindex="-1"><a class="header-anchor" href="#変換途中のundoの試行錯誤撤退メモ"><span>変換途中のundoの試行錯誤撤退メモ</span></a></h3><p>insertなどにundoTrackをfalseにするモードが追加されたので、clearCompositionとかだけundo情報を持たせなければいいんじゃないか、と思ったが、 clearCompositionがcommitTextの後に呼ばれるとUndo情報のpointがずれるのでうまくいかなかった。 conversionModeは順番変えるだけで直せたが、 例えばひがらなの「の」などでうまくいかない。 これはskk.jsのhandleKeyEventでkeyHandlerを呼んでからupdateCompositionとかclearCompositionをするからで、これを直すのは手間なので撤退した。</p>`,14)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};